package net.officefloor.hq.app.sheet;

import java.time.LocalDate;
import java.time.format.DateTimeParseException;
import net.officefloor.plugin.variable.Out;
import org.springframework.web.bind.annotation.RequestBody;

public class ValidateToday {
    public void validate(@RequestBody TodayRequest request, Out<LocalDate> today, Out<TodayRequest> body) throws InvalidSheetException {
        if (request == null || request.user() == null || request.user().isBlank()) {
            throw new InvalidSheetException("Sign in before changing the sheet's today.");
        }
        String raw = request.today() == null ? "" : request.today().trim();
        if (!raw.matches("\\d{4}-\\d{2}-\\d{2}")) {
            throw new InvalidSheetException("Today must be a date (yyyy-mm-dd).");
        }
        try {
            today.set(LocalDate.parse(raw));
            body.set(new TodayRequest(request.user().trim(), raw));
        } catch (DateTimeParseException e) {
            throw new InvalidSheetException("Today must be a real date (yyyy-mm-dd).");
        }
    }
}
package net.officefloor.hq.app.sheet;

import org.springframework.web.bind.annotation.PathVariable;

/** Fails when the sheet id has never been loaded. */
public class LoadSheet {
    public void load(@PathVariable("sheetId") String sheetId, SheetRepository repository)
            throws SheetNotFoundException {
        String id = sheetId == null ? "" : sheetId.trim();
        if (!repository.exists(id)) {
            throw new SheetNotFoundException(id);
        }
    }
}
package net.officefloor.hq.app.period;

import net.officefloor.hq.app.role.RoleRepository;
import net.officefloor.hq.app.setting.SettingRepository;
import net.officefloor.plugin.variable.Out;
import net.officefloor.plugin.variable.Val;
import org.springframework.web.bind.annotation.PathVariable;

/** Reopen the named closed or soft-closed period, dropping its fixed due-total so it is live again. Refused when the user's role may
 *  not reopen (the sheet's permission matrix; by default a steward only), there is no such period, it is locked, or it is neither closed nor soft-closed. */
public class ReopenPeriod {
    public void reopen(@PathVariable("sheetId") String sheetId, @PathVariable("periodName") String periodName,
            @Val PeriodCloseInput input, PeriodRepository periods, RoleRepository roles, SettingRepository settings,
            Out<Period> reopened) throws InvalidPeriodException {
        String id = sheetId.trim();
        periods.lockSheet(id);
        if (!settings.permissions(id).allows("reopen", roles.of(id, input.user()))) {
            throw new InvalidPeriodException("Your role may not reopen a period on this sheet.");
        }
        Period period = periods.find(id, periodName);
        if (period == null) {
            throw new InvalidPeriodException("There is no period " + periodName.trim() + " on this sheet.");
        }
        if (periods.locked(period)) {
            throw new InvalidPeriodException("The period " + period.name() + " is locked: unlock it before reopening.");
        }
        if (!(period.closed() || period.soft()) || !periods.reopen(period)) {
            throw new InvalidPeriodException("The period " + period.name() + " is not closed.");
        }
        reopened.set(new Period(period.sheetId(), period.name(), period.from(), period.to(), false, null, false, period.cap()));
    }
}

